import { LAST_CONTENT_REVIEWED, withSiteName } from '../data/site';

export type GuideCategory = 'heritage' | 'visit' | 'nearby' | 'itinerary';

export interface GuideSection {
  h2: string;
  paragraphs: string[];
  bullets?: string[];
}

export interface GuideFact {
  label: string;
  value: string;
}

export interface GuidePage {
  slug: string;
  title: string;
  seoTitle: string;
  description: string;
  category: GuideCategory;
  eyebrow: string;
  lead: string;
  facts: GuideFact[];
  sections: GuideSection[];
  faqs: [string, string][];
  related: string[];
  sources: GuideSourceKey[];
  updated: string;
}

interface GuideSeed {
  slug: string;
  title: string;
  description: string;
  category: GuideCategory;
  focus: string;
  idealFor: string;
  angle: string;
  highlights: string[];
  checks: string[];
  related: string[];
  sources?: GuideSourceKey[];
  eyebrow?: string;
  lead?: string;
  facts?: GuideFact[];
  sections?: GuideSection[];
  faqs?: [string, string][];
}

