export type GuideSourceKey = keyof typeof guideSources;

const defaultSources: Record<GuideCategory, GuideSourceKey[]> = {
  heritage: ['danangTourism', 'heritageRestoration', 'unesco', 'wardGov'],
  visit: ['heritageTickets', 'danangTourism', 'maps', 'wardGov'],
  nearby: ['danangTourism', 'vietnamTravel', 'maps'],
  itinerary: ['heritageTickets', 'danangTourism', 'vietnamTravel', 'maps'],
};

function categoryEyebrow(category: GuideCategory): string {
  return {
    heritage: 'CHỦ ĐỀ DI TÍCH',
    visit: 'LÊN KẾ HOẠCH',
    nearby: 'QUANH CHÙA CẦU',
    itinerary: 'LỘ TRÌNH GỢI Ý',
  }[category];
}

function buildLead(seed: GuideSeed): string {
  return `${seed.title} tập trung vào ${seed.focus}. Trang này phù hợp với ${seed.idealFor}, và được viết theo hướng ${seed.angle}.`;
}

function buildFacts(seed: GuideSeed): GuideFact[] {
  return [
    { label: 'Trọng tâm', value: seed.focus },
    { label: 'Phù hợp với', value: seed.idealFor },
    { label: 'Cập nhật', value: LAST_CONTENT_REVIEWED },
  ];
}

function buildSections(seed: GuideSeed): GuideSection[] {
  const categoryLabel = guideCategories[seed.category].label.toLowerCase();
  return [
    {
      h2: 'Trang này giúp gì cho chuyến đi',
      paragraphs: [
        `${seed.title} không cố thay thế thông báo tại chỗ. Mục tiêu của trang là giúp bạn ra quyết định nhanh hơn trong nhóm chủ đề ${categoryLabel}, thay vì chỉ gom thông tin rời rạc.`,
        `Với câu hỏi về ${seed.focus}, điều quan trọng nhất là hiểu bối cảnh thực tế của Chùa Cầu và khu phố cổ, rồi mới quyết định có nên thêm, bớt hay đổi nhịp hành trình.`,
      ],
      bullets: seed.highlights,
    },
    {
      h2: 'Những điểm nên ưu tiên',
      paragraphs: [
        seed.angle,
        `Khi áp dụng vào thực tế, bạn nên xem bài này như một khung suy nghĩ: chọn đúng mục tiêu của buổi đi, giữ tuyến vừa sức và tránh nhầm giữa thông tin nền trên mạng với điều kiện vận hành trong ngày.`,
      ],
    },
    {
      h2: 'Những điều nên kiểm tra trước khi đi',
      paragraphs: [
        'Các quyết định tốt nhất thường đến từ vài bước kiểm tra rất ngắn trước chuyến đi hoặc ngay tại chỗ. Điều đó đặc biệt đúng với vé, thời tiết, điều tiết giao thông và khả năng tiếp cận.',
        'Nếu một thông tin ảnh hưởng trực tiếp tới an toàn, thời gian hoặc tiền bạc, hãy xác nhận lại với bảng thông báo, quầy vé hoặc đơn vị đang trực trong ngày.',
      ],
      bullets: seed.checks,
    },
  ];
}

function buildFaqs(seed: GuideSeed): [string, string][] {
  return [
    [
      `Khi nào nên đọc bài "${seed.title}"?`,
      `Hãy đọc khi bạn đang cân nhắc ${seed.focus.toLowerCase()} và muốn biết nó có thật sự đáng đưa vào lịch trình hay không.`,
    ],
    [
      'Bài này có thay thế thông tin tại chỗ không?',
      'Không. Bài viết chỉ giúp bạn lên kế hoạch tốt hơn; quyết định cuối cùng vẫn nên dựa trên điều kiện thực tế trong ngày đi.',
    ],
  ];
}

function toPage(seed: GuideSeed): GuidePage {
  return {
    slug: seed.slug,
    title: seed.title,
    seoTitle: withSiteName('vi', seed.title),
    description: seed.description,
    category: seed.category,
    eyebrow: seed.eyebrow ?? categoryEyebrow(seed.category),
    lead: seed.lead ?? buildLead(seed),
    facts: seed.facts ?? buildFacts(seed),
    sections: seed.sections ?? buildSections(seed),
    faqs: seed.faqs ?? buildFaqs(seed),
    related: seed.related,
    sources: seed.sources ?? defaultSources[seed.category],
    updated: LAST_CONTENT_REVIEWED,
  };
}

