export const guides = seeds.map(toPage);
export const guideBySlug = new Map(guides.map((guide) => [guide.slug, guide]));
export const guideCount = guides.length;

export function getGuide(slug: string): GuidePage | undefined {
  return guideBySlug.get(slug);
}

export function getGuidesByCategory(category: GuideCategory): GuidePage[] {
  return guides.filter((guide) => guide.category === category);
}
